24	@Service
25	public class ResumoService {
26	
27	    private final Map<String, ModalidadeEntrega> modalidadesEntrega;
28	    private final Map<String, Cupom> cupons;
29	    private final Map<String, NivelClube> niveisClube;
30	    private final Map<String, FormaPagamento> formasPagamento;
31	
32	    public ResumoService(List<ModalidadeEntrega> modalidadesEntrega,
33	                          List<Cupom> cupons,
34	                          List<NivelClube> niveisClube,
35	                          List<FormaPagamento> formasPagamento) {
36	        this.modalidadesEntrega = indexarPorCodigo(modalidadesEntrega, ModalidadeEntrega::codigo);
37	        this.cupons = indexarPorCodigo(cupons, Cupom::codigo);
38	        this.niveisClube = indexarPorCodigo(niveisClube, NivelClube::codigo);
39	        this.formasPagamento = indexarPorCodigo(formasPagamento, FormaPagamento::codigo);
40	    }
41	
42	    private static <T> Map<String, T> indexarPorCodigo(List<T> itens, Function<T, String> codigo) {
43	        return itens.stream().collect(Collectors.toMap(codigo, Function.identity()));
44	    }
45	
46	    public ResumoResponse calcular(ResumoRequest pedido) {
47	        validarItens(pedido.itens());
48	        NivelClube nivel = buscarNivelClube(pedido.nivelClube());
49	        BigDecimal aliquotaSeguro = buscarAliquotaSeguro(pedido.regiao());
50	        ModalidadeEntrega modalidade = buscarModalidadeEntrega(pedido.modalidadeEntrega());
51	
52	        BigDecimal pesoTotal = somarPeso(pedido.itens());
53	        if (!modalidade.disponivel(pesoTotal)) {
54	            throw new PedidoInvalidoException(CodigoErro.MODALIDADE_INDISPONIVEL);
55	        }
56	
57	        Cupom cupom = buscarCupomSeInformado(pedido.cupom());
58	
59	        BigDecimal subtotalProdutos = Arredondamento.paraCentavos(somarSubtotal(pedido.itens()));
60	        BigDecimal frete = nivel.freteGratis()
61	                ? Arredondamento.ZERO_CENTAVOS
62	                : Arredondamento.paraCentavos(modalidade.custo(pesoTotal));
63	
64	        CupomContexto contextoCupom = new CupomContexto(subtotalProdutos, pedido.itens(), frete);
65	        if (cupom != null && !cupom.aplicavel(contextoCupom)) {
66	            throw new PedidoInvalidoException(CodigoErro.CUPOM_NAO_APLICAVEL);
67	        }
68	
69	        FormaPagamento formaPagamento = buscarFormaPagamento(pedido.formaPagamento());
70	        int parcelas = pedido.parcelasOuPadrao();
71	        if (!formaPagamento.parcelasPermitidas(parcelas)) {
72	            throw new PedidoInvalidoException(CodigoErro.PARCELAMENTO_INVALIDO);
73	        }
74	
75	        BigDecimal descontoCupom = cupom == null
76	                ? Arredondamento.ZERO_CENTAVOS
77	                : Arredondamento.paraCentavos(cupom.desconto(contextoCupom));
78	
79	        BigDecimal seguro = Arredondamento.paraCentavos(subtotalProdutos.multiply(aliquotaSeguro));
80	
81	        BigDecimal totalPedido = Arredondamento.paraCentavos(
82	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
83	
84	        if (!formaPagamento.disponivel(totalPedido)) {
85	            throw new PedidoInvalidoException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
86	        }
87	
88	        ResultadoPagamento resultadoPagamento = formaPagamento.calcular(totalPedido, parcelas);
89	        BigDecimal ajustePagamento = resultadoPagamento.valorFinal().subtract(totalPedido);
90	
91	        BigDecimal credito = Arredondamento.paraCentavos(nivel.credito(subtotalProdutos));
92	        boolean brinde = nivel.brinde(subtotalProdutos);
93	
94	        return new ResumoResponse(
95	                subtotalProdutos,
96	                descontoCupom,
97	                frete,
98	                modalidade.prazoDias(),
99	                seguro,
100	                ajustePagamento,
101	                resultadoPagamento.valorFinal(),
102	                parcelas,
103	                resultadoPagamento.valorParcela(),
104	                credito,
105	                brinde
106	        );
107	    }
108	
109	    private void validarItens(List<ItemRequest> itens) {
110	        if (itens == null || itens.isEmpty() || itens.stream().anyMatch(item -> !item.valido())) {
111	            throw new PedidoInvalidoException(CodigoErro.PEDIDO_INVALIDO);
112	        }
113	    }
114	
115	    private NivelClube buscarNivelClube(String codigo) {
116	        NivelClube nivel = codigo == null ? null : niveisClube.get(codigo);
117	        if (nivel == null) {
118	            throw new PedidoInvalidoException(CodigoErro.NIVEL_CLUBE_INVALIDO);
119	        }
120	        return nivel;
121	    }
122	
123	    private BigDecimal buscarAliquotaSeguro(String regiao) {
124	        BigDecimal aliquota = regiao == null ? null : AliquotaSeguro.para(regiao);
125	        if (aliquota == null) {
126	            throw new PedidoInvalidoException(CodigoErro.REGIAO_INVALIDA);
127	        }
128	        return aliquota;
129	    }
130	
131	    private ModalidadeEntrega buscarModalidadeEntrega(String codigo) {
132	        ModalidadeEntrega modalidade = codigo == null ? null : modalidadesEntrega.get(codigo);
133	        if (modalidade == null) {
134	            throw new PedidoInvalidoException(CodigoErro.MODALIDADE_INVALIDA);
135	        }
136	        return modalidade;
137	    }
138	
139	    private Cupom buscarCupomSeInformado(String codigo) {
140	        if (codigo == null) {
141	            return null;
142	        }
143	        Cupom cupom = cupons.get(codigo);
144	        if (cupom == null) {
145	            throw new PedidoInvalidoException(CodigoErro.CUPOM_INVALIDO);
146	        }
147	        return cupom;
148	    }
149	
150	    private FormaPagamento buscarFormaPagamento(String codigo) {
151	        FormaPagamento forma = codigo == null ? null : formasPagamento.get(codigo);
152	        if (forma == null) {
153	            throw new PedidoInvalidoException(CodigoErro.FORMA_PAGAMENTO_INVALIDA);
154	        }
155	        return forma;
156	    }
157	
158	    private BigDecimal somarSubtotal(List<ItemRequest> itens) {
159	        return itens.stream().map(ItemRequest::valorTotal).reduce(BigDecimal.ZERO, BigDecimal::add);
160	    }
161	
162	    private BigDecimal somarPeso(List<ItemRequest> itens) {
163	        return itens.stream().map(ItemRequest::pesoTotal).reduce(BigDecimal.ZERO, BigDecimal::add);
164	    }
165	}
