9	public class Leve3Pague2 implements Cupom {
10	
11	    private static final int UNIDADES_POR_GRATUIDADE = 3;
12	
13	    @Override
14	    public String codigo() {
15	        return "LEVE3PAGUE2";
16	    }
17	
18	    @Override
19	    public boolean aplicavel(CupomContexto contexto) {
20	        return true;
21	    }
22	
23	    @Override
24	    public BigDecimal desconto(CupomContexto contexto) {
25	        BigDecimal total = BigDecimal.ZERO;
26	        for (ItemRequest item : contexto.itens()) {
27	            int unidadesGratis = item.quantidade() / UNIDADES_POR_GRATUIDADE;
28	            total = total.add(item.precoUnitario().multiply(BigDecimal.valueOf(unidadesGratis)));
29	        }
30	        return total;
31	    }
32	}
