1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.comum.Arredondamento;
4	import org.springframework.stereotype.Component;
5	
6	import java.math.BigDecimal;
7	import java.math.MathContext;
8	
9	@Component
10	public class Cartao implements FormaPagamento {
11	
12	    private static final int PARCELAS_MINIMAS = 1;
13	    private static final int PARCELAS_MAXIMAS = 12;
14	    private static final int PARCELAS_SEM_JUROS = 3;
15	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
16	    private static final MathContext PRECISAO = new MathContext(20);
17	
18	    @Override
19	    public String codigo() {
20	        return "CARTAO";
21	    }
22	
23	    @Override
24	    public boolean parcelasPermitidas(int parcelas) {
25	        return parcelas >= PARCELAS_MINIMAS && parcelas <= PARCELAS_MAXIMAS;
26	    }
27	
28	    @Override
29	    public boolean disponivel(BigDecimal totalPedido) {
30	        return true;
31	    }
32	
33	    @Override
34	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
35	        if (parcelas <= PARCELAS_SEM_JUROS) {
36	            BigDecimal valorParcela = Arredondamento.paraCentavos(
37	                    totalPedido.divide(BigDecimal.valueOf(parcelas), PRECISAO));
38	            return new ResultadoPagamento(totalPedido, valorParcela);
39	        }
40	
41	        BigDecimal fatorComposto = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, PRECISAO);
42	        BigDecimal denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fatorComposto, PRECISAO));
43	        BigDecimal parcelaBruta = totalPedido.multiply(TAXA_MENSAL).divide(denominador, PRECISAO);
44	        BigDecimal valorParcela = Arredondamento.paraCentavos(parcelaBruta);
45	        BigDecimal valorFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
46	        return new ResultadoPagamento(valorFinal, valorParcela);
47	    }
48	}
