        assertErro(pedido, CodigoErro.CUPOM_NAO_APLICAVEL);
    }

    @Test
    void formaPagamentoInvalidaGeraErro() {
        ResumoRequest pedido = new ResumoRequest(
                List.of(item("Caixa", "10.00", 1, "1.00")),
                "ECONOMICA", null, "CHEQUE", null, "BRONZE", "SUDESTE");

