    }

    @Test
    void parcelamentoInvalidoParaPixGeraErro() {
        ResumoRequest pedido = new ResumoRequest(
                List.of(item("Caixa", "10.00", 1, "1.00")),
                "ECONOMICA", null, "PIX", 2, "BRONZE", "SUDESTE");

